CODE="import sys,json,pathlib,unittest,io,agent_message\nassert sys.executable == '/opt/worker/prime/prime-agent-runtime/.venv/bin/python'\nmessage_outcome=None\ntry:\n    receipt=await agent_message.send('bounded no-model diagnostic',receiver_role='parent')\n    message_outcome={'receipt':receipt}\nexcept Exception as e:\n    message_outcome={'error_class':type(e).__name__,'message':str(e)[:1500]}\nclass Tiny(unittest.TestCase):\n    def test_expression(self):self.assertEqual(2+2,4)\n    def test_filesystem(self):\n        p=pathlib.Path('/workspace/repo/skill-smoke.txt');p.write_text('ok');self.assertEqual(p.read_text(),'ok')\nr=unittest.TextTestRunner(stream=io.StringIO()).run(unittest.defaultTestLoader.loadTestsFromTestCase(Tiny))\nassert r.wasSuccessful()\nproof={'kernel_python':sys.executable,'agent_message_module':agent_message.__file__,'agent_message_outcome':message_outcome,'tests':r.testsRun,'failures':len(r.failures),'errors':len(r.errors)}\npathlib.Path('/workspace/repo/native-kernel-result.json').write_text(json.dumps(proof))\nprint('AGENT_MESSAGE_PROOF='+json.dumps(proof))\n"
SESSION="// One in-process acpx runtime and one live handle. No reconnection/recreation.\nimport { timingSafeEqual } from 'node:crypto';\nexport class Session {\n  constructor(runtime, token, id, { clock = () => performance.now(), idleMs = 1800000, maxMs = 7200000, cwd = '/workspace/repo' } = {}) {\n    if (!/^[a-f0-9]{64}$/.test(token)) throw Error('invalid credential');\n    this.runtime=runtime; this.token=token; this.id=id; this.clock=clock;\n    this.idleMs=idleMs; this.maxMs=maxMs; this.born=clock(); this.last=this.born;\n    this.cwd=cwd; this.handle=null; this.turn=null; this.closed=false; this.reason=null;\n    this.records=new Map(); this.closing=null;\n  }\n  authorized(header) {\n    const a=Buffer.from(header || ''); const b=Buffer.from('Bearer '+this.token);\n    return a.length===b.length && timingSafeEqual(a,b);\n  }\n  async initialize() {\n    if(this.handle || this.closed) throw Error('already initialized');\n    this.handle=await this.runtime.ensureSession({sessionKey:this.id, agent:'prime', mode:'persistent',\n      cwd:this.cwd, sessionOptions:{allowedTools:[], maxTurns:1}});\n  }\n  status() { return {session_id:this.id, acp_session_id:this.handle?.backendSessionId ?? this.handle?.agentSessionId,\n    backend_session_id:this.handle?.backendSessionId, record_id:this.handle?.acpxRecordId,\n    state:this.closed?'closed':this.turn?'busy':'ready',reason:this.reason,\n    requests:[...this.records.values()].map(({request_id,state})=>({request_id,state}))}; }\n  async tick() {\n    if(this.closed)return;\n    if(this.clock()-this.born>=this.maxMs) await this.close('absolute_timeout');\n    else if(!this.turn && this.clock()-this.last>=this.idleMs)await this.close('idle_timeout');\n  }\n  submit(d) {\n    if(this.closed || !this.handle)throw Error('closed_or_not_ready');\n    if(!d || Object.keys(d).some(k=>!['request_id','prompt'].includes(k)) ||\n       !/^[0-9a-f]{8}-[0-9a-f-]{27}$/.test(d.request_id || '') ||\n       typeof d.prompt!=='string' || !d.prompt.trim() || Buffer.byteLength(d.prompt)>4096)throw Error('invalid_request');\n    // No queue and no automatic replay after an ambiguous client disconnect.\n    if(this.records.has(d.request_id))throw Error('duplicate_request');\n    if(this.turn)throw Error('busy');\n    if(this.records.size>=256)throw Error('session_request_limit');\n    const record={request_id:d.request_id,state:'accepted',text:'',tools:new Map(),tools_truncated:false,truncated:false};\n    this.records.set(d.request_id,record); this.last=this.clock();\n    try {\n      this.turn=this.runtime.startTurn({handle:this.handle, mode:'prompt',requestId:d.request_id,\n        text:d.prompt,timeoutMs:120000});\n    } catch { record.state='failed_no_retry'; this.last=this.clock(); throw Error('start_uncertain'); }\n    const turn=this.turn;\n    record.done=(async()=>{\n      try {\n        await turn.promptStarted;\n        record.state='running';\n        for await(const e of turn.events) {\n          // Only allowlisted tool metadata; never args, raw output or thoughts.\n          if(e.type==='tool_call' && typeof e.toolCallId==='string' && e.toolCallId.length<=128) {\n            if(record.tools.has(e.toolCallId) || record.tools.size<256) {\n              const previous=record.tools.get(e.toolCallId) || {kind:'other',status:'unknown'};\n              const kind=['read','edit','delete','move','search','execute','fetch','think','switch_mode','other'].includes(e.kind)?e.kind:previous.kind;\n              const status=['pending','in_progress','completed','failed'].includes(e.status)?e.status:previous.status;\n              const hint=/missing default Python packages/.test(String(e.text || ''))?'kernel_missing_default_packages':/kernel startup failed/.test(String(e.text || ''))?'kernel_startup_failed':previous.hint;\n              record.tools.set(e.toolCallId,{kind,status,hint});\n            } else record.tools_truncated=true;\n          }\n          // Expose assistant output only, not thoughts or arbitrary raw ACP data.\n          if(e.type==='text_delta' && e.stream!=='thought') {\n            const text=String(e.text || '').split(this.token).join('[REDACTED]');\n            if(Buffer.byteLength(record.text+text)<=65536)record.text+=text;\n            else record.truncated=true;\n          }\n        }\n        const r=await turn.result;\n        record.state=['completed','cancelled'].includes(r.status)?r.status:'failed_no_retry';\n        record.stop_reason=r.stopReason;\n      } catch { record.state='uncertain_no_retry'; }\n      finally { this.turn=null; this.last=this.clock(); }\n    })();\n    return {request_id:d.request_id,state:'accepted',session_id:this.id};\n  }\n  result(id) {\n    const r=this.records.get(id); if(!r)throw Error('unknown_request');\n    const tools=[...r.tools.values()], kinds={};\n    for(const tool of tools)kinds[tool.kind]=(kinds[tool.kind] || 0)+1;\n    return {request_id:r.request_id,state:r.state,text:r.text,truncated:r.truncated,\n      tool_summary:{total:tools.length,completed:tools.filter(t=>t.status==='completed').length,\n        failed:tools.filter(t=>t.status==='failed').length,kinds,failure_hints:[...new Set(tools.filter(t=>t.status==='failed' && t.hint).map(t=>t.hint))],truncated:r.tools_truncated},\n      stop_reason:r.stop_reason,session_id:this.id,acp_session_id:this.handle?.backendSessionId ?? this.handle?.agentSessionId};\n  }\n  async cancel() { if(this.turn)await this.turn.cancel({reason:'owner_cancel'}); }\n  async close(reason='owner_close') {\n    if(this.closing)return this.closing;\n    this.closed=true;this.reason=reason;\n    this.closing=(async()=>{\n      try { await this.cancel(); }\n      finally {\n        try { if(this.handle)await this.runtime.close({handle:this.handle,reason,discardPersistentState:false}); }\n        finally { await this.runtime.shutdown?.(); }\n      }\n    })();\n    return this.closing;\n  }\n}\n"
NODE="import {createAcpRuntime,createFileSessionStore,createAgentRegistry} from 'acpx/runtime';\nimport {Session} from './probe-session.mjs';\nimport {randomUUID} from 'node:crypto';\nconst extra=process.argv[2]==='explicit'?['--skill','/opt/worker/prime/skills/agent-message']:[];\nconst agent=['/usr/local/bin/prime-agent','--offline','--mode','acp','--daemon-socket',process.env.PRIME_AGENT_DAEMON_SOCKET,'--no-session','--provider','fixture','--model','fixture','--no-context-files','--no-skills','--no-prompt-templates','--system-prompt','Keep this conversation alive between messages. No delegation or hidden retries.',...extra];\nconst runtime=createAcpRuntime({cwd:'/workspace/repo',sessionStore:createFileSessionStore({stateDir:'/tmp/acp-probe-'+process.argv[2]}),agentRegistry:createAgentRegistry({overrides:{prime:agent}}),permissionMode:'deny-all',nonInteractivePermissions:'deny',fs:false,terminal:false,timeoutMs:90000,agentProcessEnvAllow:['PATH','HOME','PI_OFFLINE','PRIME_AGENT_CODING_AGENT_DIR','PRIME_AGENT_DAEMON_SOCKET','PRIME_AGENT_KERNEL_PYTHON'],agentProcessEnvBlock:['LLM_API_KEY','VAULT_TOKEN']});\nconst session=new Session(runtime,'0'.repeat(64),randomUUID());\ntry {await session.initialize();const id=randomUUID();session.submit({request_id:id,prompt:'Run the fixed no-model kernel diagnostic.'});await session.records.get(id).done;console.log(JSON.stringify({session:session.status(),result:session.result(id),agent_argv:agent}));}\nfinally {await session.close('diagnostic_done');}\n"
